import base64, os
os.makedirs("/home/user/paper", exist_ok=True)
files = {
  "references.bib": "",
  "colm2026_conference.sty": "",
  "colm2026_conference.bst": "",
  "fancyhdr.sty": "",
  "natbib.sty": "",
  "main.tex": "",
  "math_commands.tex": "",
}
for name, b64data in files.items():
    with open(f"/home/user/paper/{name}", "wb") as f:
        f.write(base64.b64decode(b64data))
    print(f"Wrote {name}: {len(base64.b64decode(b64data))} bytes")